    question: '木材のヤング係数に対する含水率の影響に関する次の記述のうち、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: '木材は、繊維飽和点(概ね含水率28〜30%程度)以下の範囲では、含水率が低下するほど、一般に、ヤング係数(剛性)が増加する傾向にある。', explanation: '正しい。繊維飽和点以下では乾燥が進むほど木材の剛性・強度は高まる傾向がある。' },
      { key: 'B', text: '繊維飽和点を超える含水率の範囲(自由水を含む状態)では、含水率が変化しても、ヤング係数への影響は比較的小さい。', explanation: '正しい。繊維飽和点を超える自由水の増減は、細胞壁の性質に直接影響しないため、強度・剛性への影響は小さいとされる。' },
      { key: 'C', text: '構造用製材・集成材の基準強度・基準弾性係数は、一定の含水率状態を想定して定められており、含水率の管理(乾燥)が品質確保上重要である。', explanation: '正しい。規格上の基準強度・基準弾性係数は特定の含水率条件を前提としており、含水率管理が重要となる。' },
      { key: 'D', text: '木材の含水率は、ヤング係数(剛性)には影響するが、曲げ強度等の強度性能には一切影響しない。', explanation: '誤り（本問の正解）。含水率は曲げ強度・圧縮強度等の強度性能にも影響を及ぼし、一般に含水率が低いほど(繊維飽和点以下の範囲で)強度は高くなる傾向がある。「強度性能には一切影響しない」は誤り。' },
    ],
