    choices: [
      { key: 'A', text: '免震建築物は、免震層において大きな水平変位を生じることを前提とした構造であるため、周囲の擁壁・外構等との間に、想定変位量に応じた十分なクリアランスを確保する必要がある。', explanation: '正しい。免震建築物は大きな水平変位を許容する構造であり、周囲との十分なクリアランス確保が不可欠である。' },
      { key: 'B', text: 'クリアランスが不足していると、大地震時に免震建築物が擁壁等の障害物に衝突し、免震効果が損なわれたり、建築物に損傷が生じたりするおそれがある。', explanation: '正しい。クリアランス不足による衝突は、免震効果の阻害や建物損傷につながる重大な問題である。' },
      { key: 'C', text: '免震建築物の周囲のクリアランス部分には、エキスパンションジョイントカバー等、変位に追従できる可動性のある設えが必要となる。', explanation: '正しい。クリアランス部分は人の通行や設備配管等のため、可動性のあるカバー等で処理されることが一般的である。' },
      { key: 'D', text: '免震建築物のクリアランスは、一度確保すれば、その後の経年によって確認・維持管理を行う必要は一切ない。', explanation: '誤り（本問の正解）。クリアランス部分には物品の放置や増改築等によって支障物が生じる可能性があるため、竣工後も定期的な点検・維持管理により、クリアランスが確保され続けているか確認することが重要である。' },
    ],
    correctKey: 'D',
